local ChargeItem = Class("ChargeItem")

local StoreConstants = import('Game.UI.Store.StoreConstants')

function ChargeItem:__init()
    self.dojo = nil
end

function ChargeItem:__delete()
    self.dojo = nil
end

function ChargeItem:Awake()
    KTool.SetActive(self.Discount, true)
    SetButtonAction(self.Root, Bind(self, self.OnClickAction))
end

---@param dojo StoreDiamondDojo
---@param index number
function ChargeItem:RefreshState(dojo, index)
    self.dojo = dojo
    local goodsId = checkNumber(dojo.icon) == 0 and dojo.goodsId or checkNumber(dojo.icon)
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    CfUtils.FillImage(self.DiamondIcon, goodsVo.photoPath)
    CfUtils.FillImage(self.Image, string.format(StoreConstants.StoreChargeIcon, index), false)
    -- 直接是真实价格
    local num = dojo.price
    self.Desc.text = localize("购买_name__num_吨", { _num_ = num , _name_ = goodsVo.name})
    ---TMP字体没有中文，使用大A替换
    self.Charge.text = string.format("A%d", checkNumber(num))
    self.Num.text = tostring(dojo.amount)
    
    local extraNum = 0
    local extraText = ''
    local textColor = ''
    local numColor = ''
    if checkInt(dojo.isFirst) == 1 then
        -- 处理赠送
        extraNum = dojo.firstExtraNum
        extraText = localize("首次赠送")
        textColor = '#5c485f'
        numColor = '#ff1daa'
    else
        extraNum = dojo.extraGoodsNum
        extraText = localize("额外赠送")
        textColor = '#8b7f91'
        numColor = '#555555'
    end

    if checkInt(extraNum) > 0 then
        KTool.SetActive(self.Discount, true)
        local vo = goodsConfMgr:GetInstance():GetGoodsVoById(dojo.extraGoodsId)
        CfUtils.FillImage(self.ImgGoodsIcon, vo.photoPath)
        CfUtils.FillText(self.TextTitle, extraText)
        CfUtils.SetColor(self.TextTitle, XLuaUtils.HexToColor(textColor))
        CfUtils.FillText(self.TextNumber, extraNum)
        CfUtils.SetColor(self.TextNumber, XLuaUtils.HexToColor(numColor))
    else
        KTool.SetActive(self.Discount, false)
    end
end

function ChargeItem:OnClickAction()
    local description  = self.Desc.text
    SDKService:GetInstance():PayMoney({
        productId = self.dojo.productId,
        channelProductId = self.dojo.channelProductId,
        productDesc = description,
        payAmount = checkNumber(self.dojo.price),
        data = self.dojo
    })
end

return ChargeItem